<?php require '../includes/app.php';admin();require 'layout.php';require 'image-upload.php';$kinds=['service','project','blog','team','faq'];$error='';$id=(int)($_GET['id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){if(empty($_POST)&&!empty($_SERVER['CONTENT_LENGTH'])){http_response_code(413);exit('Upload exceeds the PHP request limit. Use a smaller image or increase post_max_size in php.ini.');}check();$id=(int)($_POST['id']??0);if(($_POST['action']??'')==='delete'){db()->prepare('DELETE FROM entries WHERE id=?')->execute([$id]);header('Location: entries.php');exit;}
$kind=$_POST['kind']??'';$title=trim($_POST['title']??'');$summary=trim($_POST['summary']??'');$body=trim($_POST['body']??'');$image=trim($_POST['image']??'');$pub=isset($_POST['published'])?1:0;$order=(int)($_POST['sort_order']??0);
if(!in_array($kind,$kinds,true)||!$title||strlen($title)>200||strlen($summary)>1000||strlen($body)>100000||($image&&!imagepath($image)))$error='Check the fields. Image must be a local assets/img/ path; title max 200, summary max 1,000, body max 100,000 characters.';
else{ $newUpload='';try { $newUpload=saveContentImage($_FILES['image_upload']??null); if($newUpload)$image=$newUpload; if(isset($_POST['remove_image'])&&!$newUpload)$image=''; if($id){$q=db()->prepare('UPDATE entries SET kind=?,title=?,summary=?,body=?,image=?,published=?,sort_order=? WHERE id=?');$q->execute([$kind,$title,$summary,$body,$image,$pub,$order,$id]);}else{$q=db()->prepare('INSERT INTO entries(kind,title,summary,body,image,published,sort_order) VALUES(?,?,?,?,?,?,?)');$q->execute([$kind,$title,$summary,$body,$image,$pub,$order]);}header('Location: entries.php');exit;}catch(Throwable $ex){if($newUpload)@unlink(__DIR__.'/../'.$newUpload);error_log($ex->getMessage());$error=($ex instanceof RuntimeException && !($ex instanceof PDOException)) ? $ex->getMessage() : 'Could not save content. Please try again.';}}}
$item=['id'=>0,'kind'=>'service','title'=>'','summary'=>'','body'=>'','image'=>'','published'=>0,'sort_order'=>0];if($id){$q=db()->prepare('SELECT * FROM entries WHERE id=?');$q->execute([$id]);$item=$q->fetch()?:$item;}if($error)$item=array_merge($item,$_POST,['published'=>isset($_POST['published'])?1:0]);top('Website content');?><p><?=e($error)?></p><p><a href="entries.php?new=1">Add content</a></p><?php if($id||isset($_GET['new'])||$error):?><form method="post" enctype="multipart/form-data"><?=token()?><input type="hidden" name="id" value="<?=e($item['id'])?>"><label>Type<select name="kind"><?php foreach($kinds as $k):?><option <?= $item['kind']===$k?'selected':''?> value="<?=$k?>"><?=$k?></option><?php endforeach;?></select></label><?php foreach(['title','summary','body','sort_order'] as $field):?><label><?=e(ucfirst($field))?><textarea name="<?=$field?>"><?=e($item[$field])?></textarea></label><?php endforeach;?><section style="padding:20px;background:#f5f7fb;border:1px dashed #c5d2e5;border-radius:10px;margin:20px 0"><label for="image-upload">Upload image</label><input id="image-upload" type="file" name="image_upload" accept="image/jpeg,image/png,image/webp"><p style="margin:10px 0;color:#68758a">JPG, PNG or WebP · Up to 5 MB · Maximum 6,000 pixels per side and 16 megapixels. Choose a file, then click Save content.</p><?php $preview=imagepath((string)$item['image']);?><img id="image-preview" src="<?=$preview?'../'.e($preview):''?>" alt="Content image preview" style="max-width:300px;max-height:220px;object-fit:contain;border-radius:8px;<?=$preview?'':'display:none;'?>"><p id="image-upload-status" role="status"></p><input type="hidden" name="image" value="<?=e($item['image'])?>"><?php if($preview):?><label><input type="checkbox" name="remove_image"> Remove current image</label><?php endif;?></section><label><input type="checkbox" name="published" <?=$item['published']?'checked':''?>> Published</label><button class="btn-company">Save content</button></form><?php endif;?><table><tr><th>Title</th><th>Type</th><th>Status</th><th>Actions</th></tr><?php foreach(db()->query('SELECT * FROM entries ORDER BY kind,sort_order,id DESC') as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['kind'])?></td><td><?=$r['published']?'Published':'Draft'?></td><td><a href="entries.php?id=<?=$r['id']?>">Edit</a><form method="post" data-confirm="Delete this content?"><?=token()?><input type="hidden" name="id" value="<?=$r['id']?>"><button name="action" value="delete">Delete</button></form></td></tr><?php endforeach;?></table><script>
(()=>{const input=document.getElementById('image-upload'),preview=document.getElementById('image-preview'),status=document.getElementById('image-upload-status');if(!input)return;const oldSrc=preview.getAttribute('src');let blob;input.addEventListener('change',()=>{if(blob)URL.revokeObjectURL(blob);const f=input.files[0];if(!f){preview.src=oldSrc;preview.style.display=oldSrc?'block':'none';status.textContent='';return;}if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>5*1024*1024){status.textContent='Choose a JPG, PNG or WebP image up to 5 MB.';input.value='';preview.src=oldSrc;preview.style.display=oldSrc?'block':'none';return;}blob=URL.createObjectURL(f);preview.src=blob;preview.style.display='block';status.textContent=f.name+' selected. Click Save content to upload.';});})();
</script><?php bottom();?>